//! 📦️ Native boxed output retains real typed backing before its separately funded payload initialization.
use super::{NativeReceive,NativeReceiver,NativeDecodeControl,RetainedCloneRef};
use crate::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneClose,retained_clone_grant_admits}};
use semio_framework_value_native_storage::NativeOwnedStorage;
use std::{mem::ManuallyDrop,marker::PhantomData};
pub struct NativeBoxReceiver<I:?Sized+'static,T:NativeReceive<I>>{inner:crate::owned::NativeReceiveSlot<I,T>,pending:ManuallyDrop<Option<T>>,pending_box:ManuallyDrop<Option<Box<T>>>,backing:NativeOwnedStorage<T>,retirement:RetainedCloneClose,effect:crate::native_decoding::construction::NativeReceivingEffect,closing:bool,marker:PhantomData<fn(&I)>}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"native boxed receiver has no funded owner in the required phase")}
fn control()->RetirementDemand{RetirementDemand{depth:1,..Default::default()}}
fn nested(mut d:RetirementDemand)->Result<RetirementDemand,ValueError>{d.depth=d.depth.checked_add(1).ok_or_else(invalid)?;Ok(d)}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_depth:g.maximum_depth-1,..g}}
impl<I:?Sized+'static,T:NativeReceive<I>> NativeBoxReceiver<I,T>{pub fn new()->Self{Self{inner:Default::default(),pending:ManuallyDrop::new(None),pending_box:ManuallyDrop::new(None),backing:NativeOwnedStorage::empty(),retirement:Default::default(),effect:Default::default(),closing:false,marker:PhantomData}}}
impl<I:?Sized+'static,T:NativeReceive<I>> NativeReceiver<I,Box<T>> for NativeBoxReceiver<I,T>{
 fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.closing||self.backing.initialized(){return Err(invalid())}if self.pending.is_some(){return Ok(if self.backing.reserved(){NativeOwnedStorage::<T>::move_demand()}else{NativeOwnedStorage::<T>::reserve_demand()})}nested(if self.inner.output_ready(){self.inner.take_demand()?}else{self.inner.demands(input,body,maximum_work_units)?})}
 fn advance(&mut self,input:RetainedCloneRef<'_,I>,decode:&mut NativeDecodeControl<'_>,body:usize,maximum_work_units:u64,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,crate::OriginalReceivingPrimary>{semio_framework_value_native_receiver_protocol::native_receive_zero_work!(maximum_work_units);let mut work=0;let result:Result<RetainedCloneStep,crate::OriginalReceivingPrimary>=(||{let d=self.demands(input,body,maximum_work_units)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}decode.checkpoint()?;crate::owned::receiving_capacity(decode,d.capacity_bytes)?;if self.pending.is_some(){let turn=if self.backing.reserved(){self.backing.put_from(&mut self.pending,g)}else{self.backing.reserve(g)};let turn=decode.receive_retained_work(g,turn);work=turn.work;return turn.result.map_err(Into::into)}if self.inner.output_ready(){let turn=self.inner.take(child(g));work=turn.work;let Some((value,p))=turn.result?else{return Ok(RetainedCloneStep::Progress(Default::default()))};*self.pending=Some(value);return Ok(RetainedCloneStep::Progress(p))}let turn=self.inner.advance(input,decode,body,maximum_work_units,child(g));work=turn.work;turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into)})();RetainedWorkOutcome{result,work}}
 fn output_ready(&self)->bool{!self.closing&&self.backing.initialized()}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid())}Ok(NativeOwnedStorage::<T>::box_demand())}
 fn take_work_demand(&self)->Result<u64,ValueError>{self.take_demand().map(|_|self.backing.box_work_demand())}
 fn take<'reply>(&mut self,output:&mut Option<Box<T>>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_native_receiver_protocol::OriginalEffectReply<'reply,crate::RetainedCloneStep,crate::OriginalReceivingPrimary>)->Result<semio_framework_value_native_receiver_protocol::OriginalEffectReplyComplete<'reply,crate::RetainedCloneStep,crate::OriginalReceivingPrimary>,crate::ValueError>{let turn=(||->crate::RetainedWorkPoll<RetainedCloneStep,crate::OriginalReceivingPrimary>{if !self.output_ready(){return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(invalid().into()),work:0})}match self.backing.take_box_into(output,effect){crate::RetainedWorkPoll::Pending{work}=>crate::RetainedWorkPoll::Pending{work},crate::RetainedWorkPoll::Complete(turn)=>crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:turn.result.map_err(Into::into),work:turn.work})}})();semio_framework_value_native_receiver_protocol::native_record_pure_take(turn,reply)}
 fn begin_close(&mut self){self.closing=true;self.inner.begin_close()}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.inner.terminal_is_empty(){return nested(self.inner.close_demands(body)?)}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<T>(false,&None,body)}if self.pending_box.is_some(){return self.retirement.next_owner_demands::<Box<T>>(true,&None,body)}if self.pending.is_some(){return self.retirement.next_owner_demands::<T>(true,&None,body)}if self.backing.initialized(){return Ok(control())}Ok(self.backing.release_demand())}
 semio_framework_value_native_receiver_protocol::box_close_work_quote!();
 fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::OriginalRetirementOutcome{let g=effect.grant();let mut work=0;let result:Result<RetainedCloneStep,crate::OriginalRetirementFailure>=(||{if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.inner.terminal_is_empty(){let turn=self.inner.close_step(&mut effect.reborrow(child(g),effect.maximum_work_units()).expect("retirement child exceeds original effect"));work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into)}if !self.retirement.is_empty(){let turn=self.retirement.step_granted(effect);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}if self.pending_box.is_some(){let turn=self.retirement.begin_granted(&mut self.pending_box,effect);work=turn.work;return turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)}if self.pending.is_some(){let turn=self.retirement.begin_granted(&mut self.pending,effect);work=turn.work;return turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)}if self.backing.initialized(){let turn=self.backing.take_box(g);work=turn.work;let Some((value,p))=turn.result?else{return Ok(RetainedCloneStep::Progress(Default::default()))};*self.pending_box=Some(value);return Ok(RetainedCloneStep::Progress(p))}let turn=self.backing.release(g);work=turn.work;turn.result.map_err(Into::into)})();RetainedWorkOutcome{result,work}}
 fn terminal_is_empty(&self)->bool{self.inner.terminal_is_empty()&&self.pending.is_none()&&self.pending_box.is_none()&&self.backing.terminal_is_empty()&&self.retirement.is_empty()}
}
impl<I:?Sized+'static,T:NativeReceive<I>> Drop for NativeBoxReceiver<I,T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native boxed receiver retains its actual typed owners");}}
impl<I:?Sized+'static,T:NativeReceive<I>> NativeReceive<I> for Box<T>{type Receiver=NativeBoxReceiver<I,T>;fn receiver()->Self::Receiver{NativeBoxReceiver::new()}}
